-- =====================================================================
-- 3. FUNCOES E MOTOR DETERMINISTICO (31 funcoes)
-- =====================================================================

CREATE OR REPLACE FUNCTION public.buscar_relatorios_usuario(p_user_id uuid)
 RETURNS TABLE(id uuid, nome_relatorio text, periodo_dias integer, data_geracao timestamp with time zone, total_vendas numeric, total_pedidos integer, total_clientes integer, formato_exportacao text)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        r.id,
        r.nome_relatorio,
        r.periodo_dias,
        r.data_geracao,
        r.total_vendas,
        r.total_pedidos,
        r.total_clientes,
        r.formato_exportacao
    FROM relatorios r
    WHERE r.user_id = p_user_id
    ORDER BY r.data_geracao DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calcular_item_orcamento_v3(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tipo_peca_raw text;
  v_tipo_peca text;
  v_pedra_raw text;
  v_pedra_norm text;
  v_prod_id uuid;
  v_prod_nome text;

  v_comp_cm numeric;
  v_larg_cm numeric;
  v_qtd numeric;
  v_lados_livres numeric;
  v_lados_parede numeric := 0;
  v_altura_testeira numeric;
  v_rodopia_altura numeric;
  v_rodopia_comp numeric;
  v_cuba_input text;
  v_preco_manual numeric;

  -- Cuba esculpida (dimensões e áreas das 5 partes da pedra)
  v_cuba_comp_cm numeric;
  v_cuba_larg_cm numeric;
  v_cuba_prof_cm numeric;
  v_cuba_comp_m numeric;
  v_cuba_larg_m numeric;
  v_cuba_prof_m numeric;
  v_area_cuba_fundo numeric := 0;
  v_area_cuba_laterais numeric := 0;
  v_area_cuba_frente_fundo numeric := 0;
  v_parcela_cuba_fundo numeric := 0;
  v_parcela_cuba_laterais numeric := 0;
  v_parcela_cuba_frente_fundo numeric := 0;

  v_coluna_preco text;
  v_preco_centavos bigint;
  v_preco_status text;
  v_preco_pedra numeric;
  v_preco_bancada_excedente numeric;

  v_area_m2 numeric := 0;
  v_comp_m numeric := 0;
  v_larg_m numeric := 0;

  -- Parcelas monetárias
  v_parcela_pedra numeric := 0;
  v_parcela_acabamento numeric := 0;
  v_parcela_testeira numeric := 0;
  v_parcela_rodopia numeric := 0;
  v_parcela_cuba numeric := 0;
  v_parcela_pingadeira numeric := 0;

  v_valor_unitario numeric := 0;
  v_subtotal numeric := 0;
  v_prazo_dias int := 5;

  v_cuba_obj jsonb;
  v_memoria jsonb := '[]'::jsonb;
  v_tipo_label text;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    return jsonb_build_object('ok', false, 'status', 'erro', 'erro', 'payload_invalido', 'mensagem', 'Objeto de entrada inválido.');
  end if;

  -- 1. Identificar Tipo de Peça com Mapeamento Completo de Sinônimos
  v_tipo_peca_raw := coalesce(p->>'tipo_peca', p->>'tipo', p->>'variacao', '');
  v_tipo_peca := public.norm_txt(v_tipo_peca_raw);

  if v_tipo_peca in ('soleira') then
    v_tipo_peca := 'soleira';
    v_tipo_label := 'Soleira';
    v_coluna_preco := 'Soleira';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_soleira', 5)::int;
  elsif v_tipo_peca in ('divisoria', 'divisória', 'divisoria_banheiro', 'divisoria de banheiro', 'divisoria de marmore', 'divisoria marmore') then
    v_tipo_peca := 'divisoria';
    v_tipo_label := 'Divisória';
    v_coluna_preco := 'Divisória';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_divisoria', 5)::int;
  elsif v_tipo_peca in ('peitoril') and coalesce((p->>'pingadeira')::boolean, false) = true then
    v_tipo_peca := 'peitoril_pingadeira';
    v_tipo_label := 'Peitoril com Pingadeira';
    v_coluna_preco := 'Peitoril';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_peitoril_pingadeira', 5)::int;
  elsif v_tipo_peca in ('peitoril_pingadeira', 'peitoril com pingadeira') then
    v_tipo_peca := 'peitoril_pingadeira';
    v_tipo_label := 'Peitoril com Pingadeira';
    v_coluna_preco := 'Peitoril';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_peitoril_pingadeira', 5)::int;
  elsif v_tipo_peca in ('peitoril', 'peitoril sem pingadeira') then
    v_tipo_peca := 'peitoril';
    v_tipo_label := 'Peitoril';
    v_coluna_preco := 'Peitoril';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_peitoril', 5)::int;
  elsif v_tipo_peca in ('filete') then
    v_tipo_peca := 'filete';
    v_tipo_label := 'Filete';
    v_coluna_preco := 'Filete';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_filete', 5)::int;
  elsif v_tipo_peca in ('balcao_simples', 'balcao simples', 'balcao') then
    v_tipo_peca := 'balcao_simples';
    v_tipo_label := 'Balcão Simples';
    v_coluna_preco := 'Peitoril';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_balcao_simples', 10)::int;
  elsif v_tipo_peca in ('balcao_testeira', 'balcao com testeira', 'balcao_com_testeira') then
    v_tipo_peca := 'balcao_testeira';
    v_tipo_label := 'Balcão com Testeira';
    v_coluna_preco := 'Peitoril';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_balcao_testeira', 15)::int;
  elsif v_tipo_peca in ('bancada', 'bancada_pia', 'pia', 'bancada de cozinha', 'bancada de pia', 'bancada cozinha') then
    v_tipo_peca := 'bancada';
    v_tipo_label := 'Bancada de Cozinha / Pia';
    v_coluna_preco := 'Bancada';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_bancada', 20)::int;
  elsif v_tipo_peca in ('lavatorio_simples', 'lavatorio simples', 'lavatorio') then
    v_tipo_peca := 'lavatorio_simples';
    v_tipo_label := 'Lavatório Simples';
    v_coluna_preco := 'Peitoril';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_lavatorio_simples', 10)::int;
  elsif v_tipo_peca in ('lavatorio_testeira', 'lavatorio com testeira', 'lavatorio_com_testeira') then
    v_tipo_peca := 'lavatorio_testeira';
    v_tipo_label := 'Lavatório com Testeira';
    v_coluna_preco := 'Peitoril';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_lavatorio_testeira', 15)::int;
  elsif v_tipo_peca in (
    'lavatorio_esculpido', 'lavatorio esculpido', 'esculpido',
    'lavatorio_escupido', 'lavatorio escupido', 'escupido',
    'lavatorio_escovado', 'lavatorio escovado', 'escovado',
    'balcao_esculpido', 'balcao esculpido', 'balcao_escupido', 'balcao escupido'
  ) then
    v_tipo_peca := 'lavatorio_esculpido';
    v_tipo_label := 'Lavatório Esculpido';
    v_coluna_preco := 'Peitoril';
    v_prazo_dias := public.fn_lojao_obter_parametro('prazo_dias_lavatorio_esculpido', 20)::int;
  else
    return jsonb_build_object(
      'ok', false,
      'status', 'erro',
      'erro', 'tipo_peca_invalido',
      'mensagem', 'Tipo de peça desconhecido ou não informado: "' || v_tipo_peca_raw || '".'
    );
  end if;

  -- 2. Validar Medidas e Quantidade (com largura padrão defensiva)
  if coalesce(p->>'comprimento_cm', '') !~ '^[0-9]+([.][0-9]+)?$' then
    return jsonb_build_object('ok', false, 'status', 'erro', 'erro', 'comprimento_invalido', 'mensagem', 'Comprimento em cm é obrigatório e deve ser positivo.');
  end if;
  v_comp_cm := (p->>'comprimento_cm')::numeric;
  if v_comp_cm <= 0 then
    return jsonb_build_object('ok', false, 'status', 'erro', 'erro', 'comprimento_invalido', 'mensagem', 'Comprimento deve ser maior que zero.');
  end if;

  -- Largura defensiva por tipo de peça se omitida ou <= 0
  if coalesce(p->>'largura_cm', '') ~ '^[0-9]+([.][0-9]+)?$' and (p->>'largura_cm')::numeric > 0 then
    v_larg_cm := (p->>'largura_cm')::numeric;
  else
    if v_tipo_peca in ('balcao_simples', 'balcao_testeira', 'lavatorio_simples', 'lavatorio_testeira', 'lavatorio_esculpido') then
      v_larg_cm := 50.0;
    elsif v_tipo_peca = 'bancada' then
      v_larg_cm := 60.0;
    elsif v_tipo_peca = 'divisoria' then
      v_larg_cm := 60.0;
    elsif v_tipo_peca = 'soleira' then
      v_larg_cm := 15.0;
    elsif v_tipo_peca in ('peitoril', 'peitoril_pingadeira') then
      v_larg_cm := 18.0;
    elsif v_tipo_peca = 'filete' then
      v_larg_cm := 5.0;
    else
      v_larg_cm := 50.0;
    end if;
  end if;

  v_qtd := coalesce(nullif(p->>'quantidade', '')::numeric, 1);
  if v_qtd <= 0 then
    v_qtd := 1;
  end if;

  v_comp_m := v_comp_cm / 100.0;
  v_larg_m := v_larg_cm / 100.0;
  v_area_m2 := round(v_comp_m * v_larg_m, 6);

  -- 3. Identificar Pedra e Preço
  v_pedra_raw := coalesce(p->>'pedra', p->>'produto_nome', p->>'produto', '');
  v_pedra_norm := public.norm_txt(v_pedra_raw);

  if p ? 'produto_id' and coalesce(p->>'produto_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select id, nome into v_prod_id, v_prod_nome
      from public.produtos
     where id = (p->>'produto_id')::uuid;
  elsif v_pedra_norm <> '' then
    select id, nome into v_prod_id, v_prod_nome
      from public.produtos
     where ativo
       and (
         public.norm_txt(nome) = v_pedra_norm
         or (v_pedra_norm in ('corumba', 'cinza corumba') and public.norm_txt(nome) in ('cinza corumba', 'corumba'))
         or (v_pedra_norm in ('ornamental', 'amarelo ornamental') and public.norm_txt(nome) in ('amarelo ornamental', 'ornamental'))
         or (v_pedra_norm in ('marmore branco cm', 'branco cm', 'branco comum') and public.norm_txt(nome) in ('marmore branco cm', 'branco comum'))
         or (v_pedra_norm in ('preto sao gabriel', 'preto sg', 'sao gabriel') and public.norm_txt(nome) = 'preto sao gabriel')
         or (v_pedra_norm = 'bege bahia' and public.norm_txt(nome) = 'bege bahia')
         or (v_pedra_norm = 'branco prime' and public.norm_txt(nome) = 'branco prime')
         or (v_pedra_norm = 'branco dallas' and public.norm_txt(nome) = 'branco dallas')
         or (v_pedra_norm = 'branco paraiso' and public.norm_txt(nome) = 'branco paraiso')
         or (v_pedra_norm = 'branco cristal' and public.norm_txt(nome) = 'branco cristal')
         or public.norm_txt(nome) like '%' || v_pedra_norm || '%'
       )
     order by case 
       when public.norm_txt(nome) = v_pedra_norm then 0
       when public.norm_txt(nome) like v_pedra_norm || '%' then 1
       else 2
     end
     limit 1;
  end if;

  if v_prod_id is null then
    return jsonb_build_object(
      'ok', false,
      'status', 'sob_consulta',
      'erro', 'pedra_nao_encontrada',
      'mensagem', 'Pedra "' || v_pedra_raw || '" não encontrada no catálogo de materiais.'
    );
  end if;

  -- Preço Manual (se informado)
  if p ? 'preco_manual' and coalesce((p->>'preco_manual')::numeric, 0) > 0 then
    v_preco_pedra := (p->>'preco_manual')::numeric;
    v_preco_status := 'manual';
  else
    -- Busca na matriz de preços vigente
    select m.preco_venda_centavos, m.status
      into v_preco_centavos, v_preco_status
      from public.lojao_precos_venda m
     where m.produto_id = v_prod_id
       and public.norm_txt(m.variacao) = public.norm_txt(v_coluna_preco)
       and m.status <> 'descontinuado'
     order by case when m.status = 'confirmado' then 0 else 1 end, m.versao desc
     limit 1;

    -- Fallback inteligente para Divisória: caso não encontre direto, busca Peitoril + R$ 200 (20000 centavos)
    if (v_preco_centavos is null or v_preco_centavos <= 0) and v_tipo_peca = 'divisoria' then
      select (m.preco_venda_centavos + 20000), m.status
        into v_preco_centavos, v_preco_status
        from public.lojao_precos_venda m
       where m.produto_id = v_prod_id
         and public.norm_txt(m.variacao) = 'peitoril'
         and m.status <> 'descontinuado'
       order by case when m.status = 'confirmado' then 0 else 1 end, m.versao desc
       limit 1;
    end if;

    -- Fallback complementar na tabela produto_variacoes
    if v_preco_centavos is null or v_preco_centavos <= 0 then
      select round(pv.preco * 100)::bigint, 'confirmado'
        into v_preco_centavos, v_preco_status
        from public.produto_variacoes pv
       where pv.produto_id = v_prod_id
         and public.norm_txt(pv.variacao) = public.norm_txt(v_coluna_preco)
       limit 1;

      if (v_preco_centavos is null or v_preco_centavos <= 0) and v_tipo_peca = 'divisoria' then
        select round((pv.preco + 200) * 100)::bigint, 'confirmado'
          into v_preco_centavos, v_preco_status
          from public.produto_variacoes pv
         where pv.produto_id = v_prod_id
           and public.norm_txt(pv.variacao) = 'peitoril'
         limit 1;
      end if;
    end if;

    if v_preco_centavos is null or v_preco_centavos <= 0 then
      return jsonb_build_object(
        'ok', false,
        'status', 'sob_consulta',
        'erro', 'preco_sob_consulta',
        'mensagem', 'Preço de ' || v_prod_nome || ' (coluna ' || v_coluna_preco || ') sob consulta.'
      );
    end if;

    v_preco_pedra := round(v_preco_centavos::numeric / 100.0, 2);
  end if;

  -- 4. Validar e Calcular Lados Livres e Lados na Parede
  if p ? 'lados_livres_m' and coalesce(nullif(p->>'lados_livres_m', ''), '')::numeric >= 0 then
    v_lados_livres := (p->>'lados_livres_m')::numeric;
  elsif p ? 'lados_livres' and coalesce(nullif(p->>'lados_livres', ''), '')::numeric >= 0 then
    v_lados_livres := (p->>'lados_livres')::numeric;
  elsif p ? 'parede_fundo' or p ? 'parede_frente' or p ? 'parede_esq' or p ? 'parede_dir' then
    v_lados_livres := public.fn_lojao_calcular_lados_livres(
      v_comp_cm, v_larg_cm,
      (p->>'parede_fundo')::boolean,
      (p->>'parede_frente')::boolean,
      (p->>'parede_esq')::boolean,
      (p->>'parede_dir')::boolean
    );
  end if;

  -- Padrão defensivo para balcões e lavatórios se não informado
  if v_tipo_peca in ('balcao_simples', 'balcao_testeira', 'lavatorio_testeira', 'lavatorio_esculpido') then
    if v_lados_livres is null or v_lados_livres <= 0 then
      v_lados_livres := round(v_comp_m + 2.0 * v_larg_m, 4);
    end if;
    v_lados_parede := greatest(0, round(2.0 * (v_comp_m + v_larg_m) - v_lados_livres, 4));
  else
    v_lados_livres := coalesce(v_lados_livres, 0);
    v_lados_parede := 0;
  end if;

  -- 5. Parâmetros Específicos: Testeira, Rodopia, Cuba
  if v_tipo_peca = 'lavatorio_esculpido' then
    v_altura_testeira := coalesce(nullif(p->>'altura_testeira_cm', '')::numeric, public.fn_lojao_obter_parametro('altura_testeira_esculpido_padrao_cm', 15));
  elsif v_tipo_peca in ('balcao_testeira', 'lavatorio_testeira') then
    v_altura_testeira := coalesce(nullif(p->>'altura_testeira_cm', '')::numeric, public.fn_lojao_obter_parametro('altura_testeira_padrao_cm', 10));
  else
    v_altura_testeira := coalesce(nullif(p->>'altura_testeira_cm', '')::numeric, 0);
  end if;

  -- Rodopia: comprimento e altura
  if p ? 'rodopia_comprimento_m' and coalesce(nullif(p->>'rodopia_comprimento_m', ''), '')::numeric > 0 then
    v_rodopia_comp := (p->>'rodopia_comprimento_m')::numeric;
  elsif v_lados_parede > 0 then
    v_rodopia_comp := v_lados_parede;
  else
    v_rodopia_comp := 0;
  end if;

  if p ? 'rodopia_altura_cm' and coalesce(nullif(p->>'rodopia_altura_cm', ''), '')::numeric > 0 then
    v_rodopia_altura := (p->>'rodopia_altura_cm')::numeric;
  elsif v_rodopia_comp > 0 and v_tipo_peca in ('lavatorio_esculpido', 'bancada', 'lavatorio_simples', 'lavatorio_testeira') then
    v_rodopia_altura := 10.0;
  else
    v_rodopia_altura := 0;
  end if;

  v_cuba_input := coalesce(p->>'cuba', p->>'cuba_nome', p->>'cuba_codigo', '');

  -- Dimensões da cuba esculpida
  if v_tipo_peca = 'lavatorio_esculpido' then
    v_cuba_comp_cm := coalesce(nullif(p->>'cuba_comp_cm', '')::numeric, nullif(p->>'cuba_comprimento_cm', '')::numeric, public.fn_lojao_obter_parametro('cuba_esculpida_padrao_comp_cm', 40.0));
    v_cuba_larg_cm := coalesce(nullif(p->>'cuba_larg_cm', '')::numeric, nullif(p->>'cuba_largura_cm', '')::numeric, public.fn_lojao_obter_parametro('cuba_esculpida_padrao_larg_cm', 35.0));
    v_cuba_prof_cm := coalesce(nullif(p->>'cuba_prof_cm', '')::numeric, nullif(p->>'cuba_profundidade_cm', '')::numeric, public.fn_lojao_obter_parametro('cuba_esculpida_padrao_prof_cm', 15.0));

    v_cuba_comp_m := v_cuba_comp_cm / 100.0;
    v_cuba_larg_m := v_cuba_larg_cm / 100.0;
    v_cuba_prof_m := v_cuba_prof_cm / 100.0;
  end if;

  -- 6. Executar Cálculos Específicos por Tipo de Peça

  -- ========================================================================
  -- CASO 1: SOLEIRA (m²)
  -- ========================================================================
  if v_tipo_peca = 'soleira' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);
    v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
      'rotulo', 'Pedra (Soleira)',
      'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m² (Área: ' || to_char(round(v_area_m2, 4), 'FM9999990D0000') || ' m²)',
      'valor', v_parcela_pedra
    ));

  -- ========================================================================
  -- CASO 1B: DIVISÓRIA (m² com preço da divisória = Peitoril + R$ 200/m²)
  -- ========================================================================
  elsif v_tipo_peca = 'divisoria' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);
    v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
      'rotulo', 'Pedra (Divisória)',
      'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m² (Área: ' || to_char(round(v_area_m2, 4), 'FM9999990D0000') || ' m²)',
      'valor', v_parcela_pedra
    ));

  -- ========================================================================
  -- CASO 2: PEITORIL SEM PINGADEIRA (m²)
  -- ========================================================================
  elsif v_tipo_peca = 'peitoril' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);
    v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
      'rotulo', 'Pedra (Peitoril)',
      'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m² (Área: ' || to_char(round(v_area_m2, 4), 'FM9999990D0000') || ' m²)',
      'valor', v_parcela_pedra
    ));

  -- ========================================================================
  -- CASO 3: PEITORIL COM PINGADEIRA (m² + R$ 3/m linear de comp)
  -- ========================================================================
  elsif v_tipo_peca = 'peitoril_pingadeira' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);
    v_parcela_pingadeira := round(v_comp_m * public.fn_lojao_obter_parametro('pingadeira_peitoril_m', 3.00), 2);
    v_memoria := v_memoria || jsonb_build_array(
      jsonb_build_object(
        'rotulo', 'Pedra (Peitoril)',
        'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m² (Área: ' || to_char(round(v_area_m2, 4), 'FM9999990D0000') || ' m²)',
        'valor', v_parcela_pedra
      ),
      jsonb_build_object(
        'rotulo', 'Pingadeira',
        'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m linear × R$ ' || to_char(public.fn_lojao_obter_parametro('pingadeira_peitoril_m', 3.00), 'FM9999990D00') || '/m',
        'valor', v_parcela_pingadeira
      )
    );

  -- ========================================================================
  -- CASO 4: FILETE (metro linear)
  -- ========================================================================
  elsif v_tipo_peca = 'filete' then
    v_parcela_pedra := round(v_comp_m * v_preco_pedra, 2);
    v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
      'rotulo', 'Pedra (Filete linear)',
      'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m (Largura ' || v_larg_cm || ' cm é informativa)',
      'valor', v_parcela_pedra
    ));

  -- ========================================================================
  -- CASO 5: BALCÃO SIMPLES (m² peitoril + acabamento boleado R$ 7/m lados livres + rodopia cheia)
  -- ========================================================================
  elsif v_tipo_peca = 'balcao_simples' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);
    v_parcela_acabamento := round(v_lados_livres * public.fn_lojao_obter_parametro('acabamento_balcao_simples_m', 7.00), 2);

    v_memoria := v_memoria || jsonb_build_array(
      jsonb_build_object(
        'rotulo', 'Pedra (Balcão - Coluna Peitoril)',
        'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m² (Área: ' || to_char(round(v_area_m2, 4), 'FM9999990D0000') || ' m²)',
        'valor', v_parcela_pedra
      ),
      jsonb_build_object(
        'rotulo', 'Acabamento Boleado Simples',
        'expressao', to_char(v_lados_livres, 'FM9999990D00') || ' m livres × R$ ' || to_char(public.fn_lojao_obter_parametro('acabamento_balcao_simples_m', 7.00), 'FM9999990D00') || '/m',
        'valor', v_parcela_acabamento
      )
    );

    if v_rodopia_altura > 0 and v_rodopia_comp > 0 then
      v_parcela_rodopia := round(v_rodopia_comp * (v_rodopia_altura / 100.0) * v_preco_pedra, 2);
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Rodopia Solicitada (Altura Cheia)',
        'expressao', to_char(v_rodopia_comp, 'FM9999990D00') || ' m × ' || to_char(v_rodopia_altura / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m² (Peitoril)',
        'valor', v_parcela_rodopia
      ));
    end if;

  -- ========================================================================
  -- CASO 6: BALCÃO COM TESTEIRA (m² peitoril + acabamento 45° R$ 60/m + testeira + rodopia cheia)
  -- ========================================================================
  elsif v_tipo_peca = 'balcao_testeira' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);
    v_parcela_acabamento := round(v_lados_livres * public.fn_lojao_obter_parametro('acabamento_balcao_testeira_m', 60.00), 2);
    v_parcela_testeira := round(v_lados_livres * (v_altura_testeira / 100.0) * v_preco_pedra, 2);

    v_memoria := v_memoria || jsonb_build_array(
      jsonb_build_object(
        'rotulo', 'Pedra (Balcão - Coluna Peitoril)',
        'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
        'valor', v_parcela_pedra
      ),
      jsonb_build_object(
        'rotulo', 'Acabamento Meia-Esquadria 45°',
        'expressao', to_char(v_lados_livres, 'FM9999990D00') || ' m livres × R$ ' || to_char(public.fn_lojao_obter_parametro('acabamento_balcao_testeira_m', 60.00), 'FM9999990D00') || '/m',
        'valor', v_parcela_acabamento
      ),
      jsonb_build_object(
        'rotulo', 'Pedra da Testeira (' || v_altura_testeira || ' cm)',
        'expressao', to_char(v_lados_livres, 'FM9999990D00') || ' m livres × ' || to_char(v_altura_testeira / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
        'valor', v_parcela_testeira
      )
    );

    if v_rodopia_altura > 0 and v_rodopia_comp > 0 then
      v_parcela_rodopia := round(v_rodopia_comp * (v_rodopia_altura / 100.0) * v_preco_pedra, 2);
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Rodopia Solicitada (Altura Cheia)',
        'expressao', to_char(v_rodopia_comp, 'FM9999990D00') || ' m × ' || to_char(v_rodopia_altura / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
        'valor', v_parcela_rodopia
      ));
    end if;

  -- ========================================================================
  -- CASO 7: BANCADA DE COZINHA / PIA (metro linear + excedente rodopia + cuba)
  -- ========================================================================
  elsif v_tipo_peca = 'bancada' then
    v_parcela_pedra := round(v_comp_m * v_preco_pedra, 2);
    v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
      'rotulo', 'Pedra (Bancada/Pia linear)',
      'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m (Largura até 60 cm e rodopia 10 cm inclusas)',
      'valor', v_parcela_pedra
    ));

    -- Excedente de rodopia acima de 10 cm
    if v_rodopia_altura > public.fn_lojao_obter_parametro('franquia_rodopia_padrao_cm', 10) then
      if v_rodopia_comp <= 0 then
        v_rodopia_comp := v_comp_m;
      end if;
      v_parcela_rodopia := round(v_rodopia_comp * ((v_rodopia_altura - 10.0) / 100.0) * v_preco_pedra, 2);
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Excedente de Rodopia (' || (v_rodopia_altura - 10) || ' cm acima de 10 cm)',
        'expressao', to_char(v_rodopia_comp, 'FM9999990D00') || ' m × ' || to_char((v_rodopia_altura - 10.0) / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m (Preço Bancada)',
        'valor', v_parcela_rodopia
      ));
    end if;

    -- Cuba
    v_cuba_obj := public.fn_lojao_obter_dados_cuba(v_cuba_input);
    v_parcela_cuba := (v_cuba_obj->>'preco')::numeric;
    if v_cuba_obj->>'nome' is not null then
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Cuba: ' || (v_cuba_obj->>'nome'),
        'expressao', case when v_parcela_cuba = 0 then 'Cortesia de instalação' else 'Catálogo oficial' end,
        'valor', v_parcela_cuba
      ));
    end if;

  -- ========================================================================
  -- CASO 8: LAVATÓRIO SIMPLES (m² peitoril + acabamento fixo R$ 180/R$ 200 + cuba)
  -- ========================================================================
  elsif v_tipo_peca = 'lavatorio_simples' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);

    if v_comp_cm <= public.fn_lojao_obter_parametro('limite_comprimento_lavatorio_cm', 120) then
      v_parcela_acabamento := public.fn_lojao_obter_parametro('acabamento_lavatorio_ate_120', 180.00);
      v_memoria := v_memoria || jsonb_build_array(
        jsonb_build_object(
          'rotulo', 'Pedra (Lavatório - Coluna Peitoril)',
          'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m² (Área: ' || to_char(round(v_area_m2, 4), 'FM9999990D0000') || ' m²)',
          'valor', v_parcela_pedra
        ),
        jsonb_build_object(
          'rotulo', 'Acabamento Fixo (Comprimento ≤ 120 cm)',
          'expressao', 'Tabela fixa de acabamento para até 1,20 m',
          'valor', v_parcela_acabamento
        )
      );
    else
      v_parcela_acabamento := public.fn_lojao_obter_parametro('acabamento_lavatorio_acima_120', 200.00);
      v_memoria := v_memoria || jsonb_build_array(
        jsonb_build_object(
          'rotulo', 'Pedra (Lavatório - Coluna Peitoril)',
          'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
          'valor', v_parcela_pedra
        ),
        jsonb_build_object(
          'rotulo', 'Acabamento Fixo (Comprimento > 120 cm)',
          'expressao', 'Tabela fixa de acabamento acima de 1,20 m',
          'valor', v_parcela_acabamento
        )
      );
    end if;

    -- Cuba
    v_cuba_obj := public.fn_lojao_obter_dados_cuba(v_cuba_input);
    v_parcela_cuba := (v_cuba_obj->>'preco')::numeric;
    if v_cuba_obj->>'nome' is not null then
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Cuba: ' || (v_cuba_obj->>'nome'),
        'expressao', case when v_parcela_cuba = 0 then 'Cortesia de instalação' else 'Catálogo oficial' end,
        'valor', v_parcela_cuba
      ));
    end if;

    -- Rodopia excedente se houver (>10cm)
    if v_rodopia_altura > 10 and v_rodopia_comp > 0 then
      select round(m.preco_venda_centavos::numeric / 100.0, 2)
        into v_preco_bancada_excedente
        from public.lojao_precos_venda m
       where m.produto_id = v_prod_id
         and public.norm_txt(m.variacao) = 'bancada'
         and m.status <> 'descontinuado'
       order by case when m.status = 'confirmado' then 0 else 1 end, m.versao desc
       limit 1;
      v_preco_bancada_excedente := coalesce(v_preco_bancada_excedente, v_preco_pedra);

      v_parcela_rodopia := round(v_rodopia_comp * ((v_rodopia_altura - 10.0) / 100.0) * v_preco_bancada_excedente, 2);
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Excedente de Rodopia (' || (v_rodopia_altura - 10) || ' cm)',
        'expressao', to_char(v_rodopia_comp, 'FM9999990D00') || ' m × ' || to_char((v_rodopia_altura - 10.0) / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_bancada_excedente, 'FM9999990D00') || '/m (Preço Bancada)',
        'valor', v_parcela_rodopia
      ));
    end if;

  -- ========================================================================
  -- CASO 9: LAVATÓRIO COM TESTEIRA (m² peitoril + fixo R$ 180/R$ 200 + testeira + cuba)
  -- ========================================================================
  elsif v_tipo_peca = 'lavatorio_testeira' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);

    if v_comp_cm <= public.fn_lojao_obter_parametro('limite_comprimento_lavatorio_cm', 120) then
      v_parcela_acabamento := public.fn_lojao_obter_parametro('acabamento_lavatorio_ate_120', 180.00);
      v_memoria := v_memoria || jsonb_build_array(
        jsonb_build_object(
          'rotulo', 'Pedra (Lavatório - Coluna Peitoril)',
          'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
          'valor', v_parcela_pedra
        ),
        jsonb_build_object(
          'rotulo', 'Acabamento Fixo (Comprimento ≤ 120 cm)',
          'expressao', 'Tabela fixa de acabamento para até 1,20 m',
          'valor', v_parcela_acabamento
        )
      );
    else
      v_parcela_acabamento := public.fn_lojao_obter_parametro('acabamento_lavatorio_acima_120', 200.00);
      v_memoria := v_memoria || jsonb_build_array(
        jsonb_build_object(
          'rotulo', 'Pedra (Lavatório - Coluna Peitoril)',
          'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
          'valor', v_parcela_pedra
        ),
        jsonb_build_object(
          'rotulo', 'Acabamento Fixo (Comprimento > 120 cm)',
          'expressao', 'Tabela fixa de acabamento acima de 1,20 m',
          'valor', v_parcela_acabamento
        )
      );
    end if;

    v_parcela_testeira := round(v_lados_livres * (v_altura_testeira / 100.0) * v_preco_pedra, 2);
    v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
      'rotulo', 'Pedra da Testeira (' || v_altura_testeira || ' cm)',
      'expressao', to_char(v_lados_livres, 'FM9999990D00') || ' m livres × ' || to_char(v_altura_testeira / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
      'valor', v_parcela_testeira
    ));

    -- Cuba
    v_cuba_obj := public.fn_lojao_obter_dados_cuba(v_cuba_input);
    v_parcela_cuba := (v_cuba_obj->>'preco')::numeric;
    if v_cuba_obj->>'nome' is not null then
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Cuba: ' || (v_cuba_obj->>'nome'),
        'expressao', case when v_parcela_cuba = 0 then 'Cortesia de instalação' else 'Catálogo oficial' end,
        'valor', v_parcela_cuba
      ));
    end if;

    -- Rodopia excedente se houver (>10cm)
    if v_rodopia_altura > 10 and v_rodopia_comp > 0 then
      select round(m.preco_venda_centavos::numeric / 100.0, 2)
        into v_preco_bancada_excedente
        from public.lojao_precos_venda m
       where m.produto_id = v_prod_id
         and public.norm_txt(m.variacao) = 'bancada'
         and m.status <> 'descontinuado'
       order by case when m.status = 'confirmado' then 0 else 1 end, m.versao desc
       limit 1;
      v_preco_bancada_excedente := coalesce(v_preco_bancada_excedente, v_preco_pedra);

      v_parcela_rodopia := round(v_rodopia_comp * ((v_rodopia_altura - 10.0) / 100.0) * v_preco_bancada_excedente, 2);
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Excedente de Rodopia (' || (v_rodopia_altura - 10) || ' cm)',
        'expressao', to_char(v_rodopia_comp, 'FM9999990D00') || ' m × ' || to_char((v_rodopia_altura - 10.0) / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_bancada_excedente, 'FM9999990D00') || '/m (Preço Bancada)',
        'valor', v_parcela_rodopia
      ));
    end if;

  -- ========================================================================
  -- CASO 10: LAVATÓRIO ESCULPIDO (OFICINA LOJÃO DOS MÁRMORES)
  -- ========================================================================
  elsif v_tipo_peca = 'lavatorio_esculpido' then
    v_parcela_pedra := round(v_area_m2 * v_preco_pedra, 2);

    if v_rodopia_comp > 0 and v_rodopia_altura > 0 then
      v_parcela_rodopia := round(v_rodopia_comp * (v_rodopia_altura / 100.0) * v_preco_pedra, 2);
    else
      v_parcela_rodopia := 0.00;
    end if;

    v_parcela_testeira := round(v_lados_livres * (v_altura_testeira / 100.0) * v_preco_pedra, 2);

    v_area_cuba_fundo := round(v_cuba_comp_m * v_cuba_larg_m, 6);
    v_parcela_cuba_fundo := round(v_area_cuba_fundo * v_preco_pedra, 2);

    v_area_cuba_laterais := round(2.0 * (v_cuba_larg_m * v_cuba_prof_m), 6);
    v_parcela_cuba_laterais := round(v_area_cuba_laterais * v_preco_pedra, 2);

    v_area_cuba_frente_fundo := round(2.0 * (v_cuba_comp_m * v_cuba_prof_m), 6);
    v_parcela_cuba_frente_fundo := round(v_area_cuba_frente_fundo * v_preco_pedra, 2);

    v_parcela_cuba := v_parcela_cuba_fundo + v_parcela_cuba_laterais + v_parcela_cuba_frente_fundo;

    v_parcela_acabamento := public.fn_lojao_obter_parametro('servico_lavatorio_esculpido', 500.00);

    v_memoria := v_memoria || jsonb_build_array(
      jsonb_build_object(
        'rotulo', 'Pedra (Tampo do Lavatório)',
        'expressao', to_char(v_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m² (Área: ' || to_char(round(v_area_m2, 4), 'FM9999990D0000') || ' m²)',
        'valor', v_parcela_pedra
      )
    );

    if v_parcela_rodopia > 0 then
      v_memoria := v_memoria || jsonb_build_array(jsonb_build_object(
        'rotulo', 'Pedra da Rodopia (Parede ' || v_rodopia_altura || ' cm)',
        'expressao', to_char(v_rodopia_comp, 'FM9999990D00') || ' m parede × ' || to_char(v_rodopia_altura / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
        'valor', v_parcela_rodopia
      ));
    end if;

    v_memoria := v_memoria || jsonb_build_array(
      jsonb_build_object(
        'rotulo', 'Pedra da Testeira (' || v_altura_testeira || ' cm)',
        'expressao', to_char(v_lados_livres, 'FM9999990D00') || ' m livres × ' || to_char(v_altura_testeira / 100.0, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
        'valor', v_parcela_testeira
      ),
      jsonb_build_object(
        'rotulo', 'Material Cuba Esculpida (Fundo: ' || v_cuba_comp_cm || '×' || v_cuba_larg_cm || ' cm)',
        'expressao', to_char(v_cuba_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_cuba_larg_m, 'FM9999990D00') || ' m × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
        'valor', v_parcela_cuba_fundo
      ),
      jsonb_build_object(
        'rotulo', 'Material Cuba Esculpida (2 Laterais: ' || v_cuba_larg_cm || '×' || v_cuba_prof_cm || ' cm)',
        'expressao', '2 × (' || to_char(v_cuba_larg_m, 'FM9999990D00') || ' m × ' || to_char(v_cuba_prof_m, 'FM9999990D00') || ' m) × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
        'valor', v_parcela_cuba_laterais
      ),
      jsonb_build_object(
        'rotulo', 'Material Cuba Esculpida (2 Frente/Fundo: ' || v_cuba_comp_cm || '×' || v_cuba_prof_cm || ' cm)',
        'expressao', '2 × (' || to_char(v_cuba_comp_m, 'FM9999990D00') || ' m × ' || to_char(v_cuba_prof_m, 'FM9999990D00') || ' m) × R$ ' || to_char(v_preco_pedra, 'FM9999990D00') || '/m²',
        'valor', v_parcela_cuba_frente_fundo
      ),
      jsonb_build_object(
        'rotulo', 'Serviço Artesanal Cuba Esculpida',
        'expressao', 'Mão de obra fixa oficial de confecção de rampa e acabamento 45°',
        'valor', v_parcela_acabamento
      )
    );
  end if;

  -- 7. Fechamento do Item
  v_valor_unitario := v_parcela_pedra + v_parcela_acabamento + v_parcela_testeira + v_parcela_rodopia + v_parcela_cuba + v_parcela_pingadeira;
  v_subtotal := round(v_valor_unitario * v_qtd, 2);

  return jsonb_build_object(
    'ok', true,
    'status', 'ok',
    'tipo_peca', v_tipo_peca,
    'tipo_peca_label', v_tipo_label,
    'produto_id', v_prod_id,
    'produto_nome', v_prod_nome,
    'pedra', v_prod_nome,
    'comprimento_cm', v_comp_cm,
    'largura_cm', v_larg_cm,
    'quantidade', v_qtd,
    'lados_livres_m', v_lados_livres,
    'lados_parede_m', v_lados_parede,
    'altura_testeira_cm', v_altura_testeira,
    'rodopia_altura_cm', v_rodopia_altura,
    'rodopia_comprimento_m', v_rodopia_comp,
    'cuba_esculpida_comp_cm', case when v_tipo_peca = 'lavatorio_esculpido' then v_cuba_comp_cm else null end,
    'cuba_esculpida_larg_cm', case when v_tipo_peca = 'lavatorio_esculpido' then v_cuba_larg_cm else null end,
    'cuba_esculpida_prof_cm', case when v_tipo_peca = 'lavatorio_esculpido' then v_cuba_prof_cm else null end,
    'material_total', round(v_parcela_pedra + v_parcela_rodopia + v_parcela_testeira + v_parcela_cuba, 2),
    'servico_total', v_parcela_acabamento,
    'preco_unitario_tabela', v_preco_pedra,
    'valor_unitario', v_valor_unitario,
    'subtotal', v_subtotal,
    'prazo_dias', v_prazo_dias,
    'regra_versao', 'v3.1',
    'memoria_calculo', v_memoria
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.calcular_orcamento_v3(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_itens jsonb;
  v_item jsonb;
  v_res_item jsonb;
  v_resultado_itens jsonb := '[]'::jsonb;
  v_pendencias jsonb := '[]'::jsonb;

  v_subtotal_geral numeric := 0;
  v_desconto numeric := 0;
  v_desconto_tipo text;
  v_desconto_valor numeric := 0;
  v_total numeric := 0;
  v_sinal numeric := 0;
  v_saldo numeric := 0;
  v_prazo_geral int := 0;
  v_status_final text := 'ok';
  v_ok boolean := true;
  v_indice int := 0;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    return jsonb_build_object('ok', false, 'status', 'erro', 'erro', 'payload_invalido');
  end if;

  v_itens := p_payload->'itens';
  if v_itens is null or jsonb_typeof(v_itens) <> 'array' or jsonb_array_length(v_itens) = 0 then
    return jsonb_build_object('ok', false, 'status', 'erro', 'erro', 'itens_obrigatorios');
  end if;

  for v_item in select value from jsonb_array_elements(v_itens)
  loop
    v_indice := v_indice + 1;
    v_res_item := public.calcular_item_orcamento_v3(v_item);

    if not coalesce((v_res_item->>'ok')::boolean, false) then
      v_ok := false;
      v_status_final := coalesce(v_res_item->>'status', 'erro');
      v_pendencias := v_pendencias || jsonb_build_array(jsonb_build_object(
        'indice', v_indice,
        'item', v_item,
        'erro', v_res_item->>'erro',
        'mensagem', v_res_item->>'mensagem'
      ));
    else
      v_subtotal_geral := v_subtotal_geral + (v_res_item->>'subtotal')::numeric;
      if (v_res_item->>'prazo_dias')::int > v_prazo_geral then
        v_prazo_geral := (v_res_item->>'prazo_dias')::int;
      end if;
    end if;

    v_resultado_itens := v_resultado_itens || jsonb_build_array(v_res_item);
  end loop;

  v_desconto_tipo := coalesce(p_payload->>'desconto_tipo', 'nenhum');
  v_desconto_valor := coalesce(nullif(p_payload->>'desconto_valor', '')::numeric, 0);

  if v_desconto_tipo in ('pix', 'avista_pix') then
    v_desconto := round(v_subtotal_geral * (public.fn_lojao_obter_parametro('desconto_pix_percentual', 5.00) / 100.0), 2);
  elsif v_desconto_tipo in ('percentual', '%') then
    v_desconto := round(v_subtotal_geral * (v_desconto_valor / 100.0), 2);
  elsif v_desconto_tipo in ('valor', 'dinheiro', 'reais') then
    v_desconto := least(v_desconto_valor, v_subtotal_geral);
  else
    v_desconto := 0;
  end if;

  v_total := greatest(v_subtotal_geral - v_desconto, 0);
  v_sinal := round(v_total * (public.fn_lojao_obter_parametro('sinal_percentual', 30.00) / 100.0), 2);
  v_saldo := v_total - v_sinal;

  return jsonb_build_object(
    'ok', v_ok,
    'status', v_status_final,
    'moeda', 'BRL',
    'itens', v_resultado_itens,
    'subtotal_geral', v_subtotal_geral,
    'desconto_tipo', v_desconto_tipo,
    'desconto', v_desconto,
    'total', v_total,
    'sinal_30', v_sinal,
    'saldo_70', v_saldo,
    'prazo_dias_uteis', v_prazo_geral,
    'regra_versao', 'v3.0',
    'pendencias', v_pendencias,
    'calculado_em', now()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_aprovar_orcamento(p_token uuid, p_acao text, p_ajuste_centavos bigint DEFAULT 0, p_observacoes text DEFAULT NULL::text, p_aprovado_por text DEFAULT 'link'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.lojao_orcamento_solicitacoes%rowtype;
  v_total_final bigint;
begin
  if p_acao not in ('aprovar', 'rejeitar') then
    return jsonb_build_object('ok', false, 'erro', 'acao_invalida');
  end if;

  select * into v_row
    from public.lojao_orcamento_solicitacoes
   where token_aprovacao = p_token
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'erro', 'nao_encontrado');
  end if;

  if v_row.status <> 'rascunho' then
    return jsonb_build_object('ok', false, 'erro', 'ja_processado', 'status', v_row.status);
  end if;

  if p_acao = 'aprovar' then
    v_total_final := greatest(0, v_row.total_centavos + coalesce(p_ajuste_centavos, 0));
    update public.lojao_orcamento_solicitacoes
       set status = 'aprovado',
           ajuste_centavos = coalesce(p_ajuste_centavos, 0),
           total_final_centavos = v_total_final,
           observacoes = coalesce(nullif(btrim(coalesce(p_observacoes, '')), ''), observacoes),
           aprovado_por = coalesce(nullif(btrim(coalesce(p_aprovado_por, '')), ''), 'link'),
           aprovado_em = now(),
           atualizado_em = now()
     where id = v_row.id;
  else
    update public.lojao_orcamento_solicitacoes
       set status = 'rejeitado',
           observacoes = coalesce(nullif(btrim(coalesce(p_observacoes, '')), ''), observacoes),
           aprovado_por = coalesce(nullif(btrim(coalesce(p_aprovado_por, '')), ''), 'link'),
           aprovado_em = now(),
           atualizado_em = now()
     where id = v_row.id;
  end if;

  select * into v_row
    from public.lojao_orcamento_solicitacoes
   where id = v_row.id;

  return jsonb_build_object(
    'ok', true,
    'solicitacao_id', v_row.id,
    'status', v_row.status,
    'total_centavos', v_row.total_centavos,
    'ajuste_centavos', v_row.ajuste_centavos,
    'total_final_centavos', v_row.total_final_centavos,
    'observacoes', v_row.observacoes,
    'aprovado_em', v_row.aprovado_em
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_brl(p_centavos bigint)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select replace(
           replace(
             replace(to_char(coalesce(p_centavos, 0)::numeric / 100, 'FM9,999,999,990.00'), ',', chr(1)),
             '.', ','
           ),
           chr(1), '.'
         );
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_calcular_lados_livres(p_comp_cm numeric, p_larg_cm numeric, p_parede_fundo boolean DEFAULT false, p_parede_frente boolean DEFAULT false, p_parede_esq boolean DEFAULT false, p_parede_dir boolean DEFAULT false)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_total numeric := 0;
begin
  if not coalesce(p_parede_frente, false) then
    v_total := v_total + (coalesce(p_comp_cm, 0) / 100.0);
  end if;
  if not coalesce(p_parede_fundo, false) then
    v_total := v_total + (coalesce(p_comp_cm, 0) / 100.0);
  end if;
  if not coalesce(p_parede_esq, false) then
    v_total := v_total + (coalesce(p_larg_cm, 0) / 100.0);
  end if;
  if not coalesce(p_parede_dir, false) then
    v_total := v_total + (coalesce(p_larg_cm, 0) / 100.0);
  end if;
  return round(v_total, 4);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_calcular_orcamento(p_payload jsonb, p_modo text DEFAULT 'producao'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_itens jsonb;
  v_item jsonb;
  v_indice int := 0;
  v_resultado_itens jsonb := '[]'::jsonb;
  v_pendencias jsonb := '[]'::jsonb;
  v_avisos jsonb := '[]'::jsonb;
  v_total bigint := 0;
  v_tem_sob_consulta boolean := false;
  v_tem_pendencia boolean := false;
  v_tem_rascunho boolean := false;

  v_produto_id uuid;
  v_produto_nome text;
  v_produto_tipo text;
  v_produto_ativo boolean;
  v_produto_unidade text;

  v_regra_variacao text;
  v_regra_usa_area boolean;
  v_regra_multiplicador numeric;
  v_regra_minimo numeric;
  v_regra_arredondamento text;

  v_preco_venda bigint;
  v_preco_status text;
  v_preco_origem text;
  v_preco_versao int;

  v_nome text;
  v_count int;
  v_ids uuid[];
  v_comp numeric;
  v_larg numeric;
  v_qtd numeric;
  v_area numeric;
  v_area_cobrada numeric;
  v_preco_m2 bigint;
  v_subtotal_item bigint;
  v_status_item text;
  v_motivo text;

  v_extras jsonb;
  v_extra jsonb;
  v_extra_result jsonb;
  v_extra_codigo text;
  v_extra_codigo_canonico text;
  v_extra_nome text;
  v_extra_unidade text;
  v_extra_preco bigint;
  v_extra_qtd numeric;
  v_extra_comp numeric;
  v_extra_larg numeric;
  v_extra_area numeric;
  v_extra_linear numeric;
  v_extra_valor bigint;

  v_status_final text;
  v_ok boolean;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    return jsonb_build_object('ok', false, 'erro', 'payload_invalido');
  end if;

  if p_modo not in ('producao', 'simulacao') then
    return jsonb_build_object('ok', false, 'erro', 'modo_invalido');
  end if;

  v_itens := p_payload->'itens';
  if v_itens is null or jsonb_typeof(v_itens) <> 'array' or jsonb_array_length(v_itens) = 0 then
    return jsonb_build_object('ok', false, 'erro', 'itens_obrigatorios');
  end if;

  if jsonb_array_length(v_itens) > 30 then
    return jsonb_build_object('ok', false, 'erro', 'limite_de_itens', 'limite', 30);
  end if;

  for v_item in select value from jsonb_array_elements(v_itens)
  loop
    v_indice := v_indice + 1;
    v_status_item := 'ok';
    v_motivo := null;
    v_subtotal_item := 0;
    v_preco_m2 := null;
    v_area := null;
    v_area_cobrada := null;
    v_extra_result := '[]'::jsonb;
    v_extras := '[]'::jsonb;
    v_ids := null;
    v_produto_id := null;
    v_produto_nome := null;
    v_produto_tipo := null;
    v_produto_ativo := null;
    v_produto_unidade := null;
    v_regra_variacao := null;
    v_regra_usa_area := null;
    v_regra_multiplicador := null;
    v_regra_minimo := null;
    v_regra_arredondamento := null;
    v_preco_venda := null;
    v_preco_status := null;
    v_preco_origem := null;
    v_preco_versao := null;

    -- 1. Identificar Produto
    if v_item ? 'produto_id' then
      if coalesce(v_item->>'produto_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        v_status_item := 'erro';
        v_motivo := 'produto_id_invalido';
      else
        select p.id, p.nome, p.tipo, p.ativo, p.unidade_venda
          into v_produto_id, v_produto_nome, v_produto_tipo, v_produto_ativo, v_produto_unidade
          from public.produtos p
         where p.id = (v_item->>'produto_id')::uuid;

        if not found then
          v_status_item := 'erro';
          v_motivo := 'produto_nao_encontrado';
        elsif not v_produto_ativo then
          v_status_item := 'erro';
          v_motivo := 'produto_inativo';
        end if;
      end if;
    elsif v_item ? 'produto_nome' or v_item ? 'produto' then
      v_nome := public.norm_txt(coalesce(v_item->>'produto_nome', v_item->>'produto'));
      if v_nome = '' then
        v_status_item := 'erro';
        v_motivo := 'produto_obrigatorio';
      else
        -- Busca direta ou por aproximação
        select p.id, p.nome, p.tipo, p.ativo, p.unidade_venda
          into v_produto_id, v_produto_nome, v_produto_tipo, v_produto_ativo, v_produto_unidade
          from public.produtos p
         where p.ativo
           and (public.norm_txt(p.nome) = v_nome 
                or (v_nome = 'corumba' and public.norm_txt(p.nome) = 'cinza corumba')
                or (v_nome = 'ornamental' and public.norm_txt(p.nome) = 'amarelo ornamental')
                or (v_nome = 'marmore branco cm' and public.norm_txt(p.nome) in ('marmore branco cm', 'branco comum')))
         order by case when public.norm_txt(p.nome) = v_nome then 0 else 1 end
         limit 1;

        if not found then
          v_status_item := 'erro';
          v_motivo := 'produto_nao_encontrado';
        end if;
      end if;
    else
      v_status_item := 'erro';
      v_motivo := 'produto_obrigatorio';
    end if;

    if v_status_item <> 'ok' then
      v_tem_sob_consulta := true;
      v_pendencias := v_pendencias || jsonb_build_array(jsonb_build_object(
        'tipo', 'item', 'indice', v_indice, 'motivo', v_motivo,
        'produto_id', v_item->>'produto_id', 'produto_nome', coalesce(v_item->>'produto_nome', v_item->>'produto'),
        'variacao', coalesce(v_item->>'variacao', v_item->>'tipo')
      ));
      v_resultado_itens := v_resultado_itens || jsonb_build_array(jsonb_build_object(
        'indice', v_indice, 'status', v_status_item, 'motivo', v_motivo,
        'produto', coalesce(v_produto_nome, v_item->>'produto_nome', v_item->>'produto'),
        'variacao', coalesce(v_item->>'variacao', v_item->>'tipo'),
        'subtotal_centavos', 0
      ));
      continue;
    end if;

    -- 2. Identificar Variação e Regra de Cálculo
    select rc.variacao, rc.usa_area, rc.multiplicador, rc.medida_minima_m2, rc.arredondamento
      into v_regra_variacao, v_regra_usa_area, v_regra_multiplicador, v_regra_minimo, v_regra_arredondamento
      from public.lojao_regras_calculo rc
     where rc.ativo
       and (public.norm_txt(rc.variacao) = public.norm_txt(coalesce(v_item->>'variacao', v_item->>'tipo', ''))
            or (public.norm_txt(coalesce(v_item->>'variacao', v_item->>'tipo', '')) in ('pia', 'bancada de pia') and rc.variacao = 'Bancada')
            or (public.norm_txt(coalesce(v_item->>'variacao', v_item->>'tipo', '')) in ('lavatorio simples') and rc.variacao = 'Lavatório')
            or (public.norm_txt(coalesce(v_item->>'variacao', v_item->>'tipo', '')) in ('balcao') and rc.variacao = 'Balcão Simples'))
     order by case when public.norm_txt(rc.variacao) = public.norm_txt(coalesce(v_item->>'variacao', v_item->>'tipo', '')) then 0 else 1 end
     limit 1;

    if not found then
      v_status_item := 'erro';
      v_motivo := 'variacao_nao_suportada';
    end if;

    if v_status_item <> 'ok' then
      v_tem_sob_consulta := true;
      v_pendencias := v_pendencias || jsonb_build_array(jsonb_build_object(
        'tipo', 'item', 'indice', v_indice, 'motivo', v_motivo,
        'produto_id', v_produto_id, 'produto_nome', v_produto_nome,
        'variacao', coalesce(v_item->>'variacao', v_item->>'tipo')
      ));
      v_resultado_itens := v_resultado_itens || jsonb_build_array(jsonb_build_object(
        'indice', v_indice, 'status', v_status_item, 'motivo', v_motivo,
        'produto', v_produto_nome, 'variacao', coalesce(v_item->>'variacao', v_item->>'tipo'),
        'subtotal_centavos', 0
      ));
      continue;
    end if;

    -- 3. Medidas (em centímetros)
    if coalesce(v_item->>'comprimento_cm', '') !~ '^[0-9]+([.][0-9]+)?$' then
      v_status_item := 'erro';
      v_motivo := 'comprimento_invalido';
    else
      v_comp := (v_item->>'comprimento_cm')::numeric;
      if v_comp <= 0 or v_comp > 3000 then
        v_status_item := 'erro';
        v_motivo := 'comprimento_fora_do_limite';
      end if;
    end if;

    if v_status_item = 'ok' then
      if v_regra_usa_area then
        if coalesce(v_item->>'largura_cm', '') !~ '^[0-9]+([.][0-9]+)?$' then
          v_status_item := 'erro';
          v_motivo := 'largura_invalida';
        else
          v_larg := (v_item->>'largura_cm')::numeric;
          if v_larg <= 0 or v_larg > 3000 then
            v_status_item := 'erro';
            v_motivo := 'largura_fora_do_limite';
          end if;
        end if;
      else
        -- Para peças lineares (Bancada, Lavatório, Filete), largura é opcional/informativa
        if coalesce(v_item->>'largura_cm', '') ~ '^[0-9]+([.][0-9]+)?$' then
          v_larg := (v_item->>'largura_cm')::numeric;
        else
          v_larg := 0;
        end if;
      end if;
    end if;

    if v_status_item = 'ok' then
      if coalesce(v_item->>'quantidade', '') = '' then
        v_qtd := 1;
      elsif coalesce(v_item->>'quantidade', '') !~ '^[0-9]+$' then
        v_status_item := 'erro';
        v_motivo := 'quantidade_invalida';
      else
        v_qtd := (v_item->>'quantidade')::numeric;
        if v_qtd <= 0 or v_qtd > 500 then
          v_status_item := 'erro';
          v_motivo := 'quantidade_fora_do_limite';
        end if;
      end if;
    end if;

    if v_status_item <> 'ok' then
      v_tem_sob_consulta := true;
      v_pendencias := v_pendencias || jsonb_build_array(jsonb_build_object(
        'tipo', 'item', 'indice', v_indice, 'motivo', v_motivo,
        'produto_id', v_produto_id, 'produto_nome', v_produto_nome,
        'variacao', v_regra_variacao
      ));
      v_resultado_itens := v_resultado_itens || jsonb_build_array(jsonb_build_object(
        'indice', v_indice, 'status', v_status_item, 'motivo', v_motivo,
        'produto', v_produto_nome, 'variacao', v_regra_variacao,
        'comprimento_cm', v_item->>'comprimento_cm',
        'largura_cm', v_item->>'largura_cm',
        'quantidade', v_item->>'quantidade',
        'subtotal_centavos', 0
      ));
      continue;
    end if;

    -- 4. Preço da Matriz
    select m.preco_venda_centavos, m.status, m.origem, m.versao
      into v_preco_venda, v_preco_status, v_preco_origem, v_preco_versao
      from public.lojao_precos_venda m
     where m.produto_id = v_produto_id
       and (public.norm_txt(m.variacao) = public.norm_txt(v_regra_variacao)
            or (v_regra_variacao in ('Bancada de Pia', 'Pia') and m.variacao = 'Bancada')
            or (v_regra_variacao in ('Lavatório Simples') and m.variacao = 'Lavatório')
            or (v_regra_variacao in ('Balcão Simples') and m.variacao in ('Balcão Simples', 'Peitoril')))
       and m.status <> 'descontinuado'
       and (p_modo = 'simulacao' or m.status = 'confirmado')
     order by case when m.status = 'confirmado' then 0 else 1 end, m.versao desc
     limit 1;

    if not found then
      v_status_item := 'sob_consulta';
      v_motivo := case when p_modo = 'producao' then 'preco_nao_confirmado' else 'preco_nao_configurado' end;
    elsif v_preco_venda is null or v_preco_venda <= 0 then
      v_status_item := 'sob_consulta';
      v_motivo := 'preco_zero_ou_ausente';
    end if;

    if v_status_item <> 'ok' then
      v_tem_sob_consulta := true;
      v_pendencias := v_pendencias || jsonb_build_array(jsonb_build_object(
        'tipo', 'item', 'indice', v_indice, 'motivo', v_motivo,
        'produto_id', v_produto_id, 'produto_nome', v_produto_nome,
        'variacao', v_regra_variacao
      ));
      v_resultado_itens := v_resultado_itens || jsonb_build_array(jsonb_build_object(
        'indice', v_indice, 'status', v_status_item, 'motivo', v_motivo,
        'produto', v_produto_nome, 'variacao', v_regra_variacao,
        'comprimento_cm', v_comp, 'largura_cm', v_larg, 'quantidade', v_qtd,
        'subtotal_centavos', 0
      ));
      continue;
    end if;

    -- 5. Cálculo do Subtotal Base
    v_preco_m2 := v_preco_venda;

    if v_regra_usa_area then
      -- Área em m² (comp × larg em metros)
      v_area := round((v_comp / 100.0) * (v_larg / 100.0), 6);
      v_area_cobrada := round(greatest(v_area, coalesce(v_regra_minimo, 0)) * v_qtd * coalesce(v_regra_multiplicador, 1), 6);
      v_subtotal_item := round(v_area_cobrada * v_preco_m2)::bigint;
    else
      -- Metro linear (comprimento em metros × preço linear × quantidade)
      v_area := round(v_comp / 100.0, 4);
      v_area_cobrada := round((v_comp / 100.0) * v_qtd * coalesce(v_regra_multiplicador, 1), 4);
      v_subtotal_item := round((v_comp / 100.0) * v_qtd * coalesce(v_regra_multiplicador, 1) * v_preco_m2)::bigint;
    end if;

    if v_preco_status = 'rascunho' then
      v_tem_rascunho := true;
    end if;

    -- 6. Processar Extras
    v_extras := coalesce(v_item->'extras', '[]'::jsonb);
    if jsonb_typeof(v_extras) <> 'array' then
      v_extras := '[]'::jsonb;
    end if;

    for v_extra in select value from jsonb_array_elements(v_extras)
    loop
      v_extra_codigo := public.norm_txt(coalesce(v_extra->>'codigo', ''));
      if v_extra_codigo = '' then
        continue;
      end if;

      select r.codigo, r.nome, r.unidade, r.preco_centavos
        into v_extra_codigo_canonico, v_extra_nome, v_extra_unidade, v_extra_preco
        from public.lojao_regras_extras r
       where r.ativo
         and (public.norm_txt(r.codigo) = v_extra_codigo or public.norm_txt(r.nome) = v_extra_codigo)
       limit 1;

      if not found or v_extra_preco is null or v_extra_preco <= 0 then
        v_tem_pendencia := true;
        v_pendencias := v_pendencias || jsonb_build_array(jsonb_build_object(
          'tipo', 'extra', 'indice', v_indice, 'codigo', v_extra_codigo,
          'motivo', 'extra_nao_configurado'
        ));
        continue;
      end if;

      v_extra_qtd := coalesce(nullif(v_extra->>'quantidade', '')::numeric, 1);
      v_extra_valor := 0;

      if v_extra_unidade = 'm2' then
        v_extra_comp := coalesce(nullif(v_extra->>'comprimento_cm', '')::numeric, v_comp);
        v_extra_larg := coalesce(nullif(v_extra->>'largura_cm', '')::numeric, 10);
        v_extra_area := (v_extra_comp / 100.0) * (v_extra_larg / 100.0) * v_extra_qtd;
        v_extra_valor := round(v_extra_area * v_extra_preco)::bigint;
      elsif v_extra_unidade = 'm_linear' then
        v_extra_comp := coalesce(nullif(v_extra->>'comprimento_cm', '')::numeric, v_comp);
        v_extra_linear := (v_extra_comp / 100.0) * v_extra_qtd;
        v_extra_valor := round(v_extra_linear * v_extra_preco)::bigint;
      elsif v_extra_unidade = 'unidade' then
        v_extra_valor := round(v_extra_qtd * v_extra_preco)::bigint;
      end if;

      v_subtotal_item := v_subtotal_item + v_extra_valor;
      v_extra_result := v_extra_result || jsonb_build_array(jsonb_build_object(
        'codigo', v_extra_codigo_canonico,
        'nome', v_extra_nome,
        'unidade', v_extra_unidade,
        'quantidade', v_extra_qtd,
        'valor_centavos', v_extra_valor,
        'valor', round(v_extra_valor::numeric / 100.0, 2)
      ));
    end loop;

    v_total := v_total + v_subtotal_item;

    v_resultado_itens := v_resultado_itens || jsonb_build_array(jsonb_build_object(
      'indice', v_indice,
      'produto_id', v_produto_id,
      'produto', v_produto_nome,
      'variacao', v_regra_variacao,
      'comprimento_cm', v_comp,
      'largura_cm', v_larg,
      'quantidade', v_qtd,
      'usa_area', v_regra_usa_area,
      'medida_m2_ou_m', round(v_area_cobrada, 4),
      'preco_unitario_centavos', v_preco_m2,
      'preco_unitario', round(v_preco_m2::numeric / 100.0, 2),
      'subtotal_centavos', v_subtotal_item,
      'subtotal', round(v_subtotal_item::numeric / 100.0, 2),
      'extras', v_extra_result,
      'status', v_status_item,
      'motivo', v_motivo
    ));
  end loop;

  v_status_final := case
    when v_tem_sob_consulta then 'sob_consulta'
    when v_tem_pendencia then 'parcial'
    else 'ok'
  end;
  v_ok := v_status_final = 'ok';

  return jsonb_build_object(
    'ok', v_ok,
    'status', v_status_final,
    'modo', p_modo,
    'moeda', 'BRL',
    'itens', v_resultado_itens,
    'subtotal_centavos', v_total,
    'desconto_centavos', 0,
    'ajuste_centavos', 0,
    'total_centavos', v_total,
    'pendencias', v_pendencias,
    'avisos', v_avisos,
    'pronto_para_aprovacao', v_status_final = 'ok',
    'pode_enviar_ao_cliente', false,
    'versao_motor', 'v2',
    'gerado_em', now()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_confirmar_preco(p_produto_id uuid, p_variacao text, p_preco_centavos bigint, p_confirmado_por text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.lojao_precos_venda%rowtype;
begin
  if p_produto_id is null or p_variacao is null or btrim(p_variacao) = '' then
    return jsonb_build_object('ok', false, 'erro', 'parametros_obrigatorios');
  end if;

  if p_preco_centavos is null or p_preco_centavos <= 0 then
    return jsonb_build_object('ok', false, 'erro', 'preco_invalido');
  end if;

  update public.lojao_precos_venda
     set preco_venda_centavos = p_preco_centavos,
         status = 'confirmado',
         origem = 'manual',
         confirmado_por = coalesce(nullif(btrim(coalesce(p_confirmado_por, '')), ''), 'manual'),
         confirmado_em = now(),
         versao = versao + 1,
         atualizado_em = now()
   where produto_id = p_produto_id
     and public.norm_txt(variacao) = public.norm_txt(p_variacao)
   returning * into v_row;

  if not found then
    return jsonb_build_object('ok', false, 'erro', 'preco_nao_encontrado');
  end if;

  return jsonb_build_object(
    'ok', true,
    'produto_id', v_row.produto_id,
    'produto_nome', v_row.produto_nome,
    'variacao', v_row.variacao,
    'preco_venda_centavos', v_row.preco_venda_centavos,
    'status', v_row.status,
    'versao', v_row.versao
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_confirmar_precos(p_itens jsonb, p_confirmado_por text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_item jsonb;
  v_ok int := 0;
  v_erros jsonb := '[]'::jsonb;
  v_resultado jsonb;
begin
  if p_itens is null or jsonb_typeof(p_itens) <> 'array' or jsonb_array_length(p_itens) = 0 then
    return jsonb_build_object('ok', false, 'erro', 'itens_obrigatorios');
  end if;

  for v_item in select value from jsonb_array_elements(p_itens)
  loop
    if coalesce(v_item->>'produto_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_item->>'preco_centavos', '') !~ '^[0-9]+$' then
      v_erros := v_erros || jsonb_build_array(jsonb_build_object(
        'ok', false, 'erro', 'item_invalido', 'item', v_item
      ));
      continue;
    end if;

    v_resultado := public.fn_lojao_confirmar_preco(
      (v_item->>'produto_id')::uuid,
      v_item->>'variacao',
      (v_item->>'preco_centavos')::bigint,
      p_confirmado_por
    );

    if (v_resultado->>'ok')::boolean then
      v_ok := v_ok + 1;
    else
      v_erros := v_erros || jsonb_build_array(v_resultado);
    end if;
  end loop;

  return jsonb_build_object(
    'ok', jsonb_array_length(v_erros) = 0,
    'confirmados', v_ok,
    'erros', v_erros
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_extrair_area_m2(p_medidas text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_texto text;
  v_match text[];
  v_a numeric;
  v_b numeric;
begin
  if p_medidas is null or btrim(p_medidas) = '' then
    return null;
  end if;

  v_texto := replace(p_medidas, ',', '.');

  -- Medidas compostas e três dimensões não entram na sugestão automática.
  if v_texto ~ '[+=]'
     or (select count(*) from regexp_matches(v_texto, '[xX×*]', 'g')) > 1 then
    return null;
  end if;

  v_match := regexp_match(v_texto, '([0-9]+(?:\.[0-9]+)?)\s*[xX×*]\s*([0-9]+(?:\.[0-9]+)?)');
  if v_match is null then
    return null;
  end if;

  v_a := v_match[1]::numeric;
  v_b := v_match[2]::numeric;
  if v_a <= 0 or v_b <= 0 then
    return null;
  end if;

  -- Números acima de 10 são centímetros; abaixo ou iguais são metros.
  if v_a > 10 then v_a := v_a / 100; end if;
  if v_b > 10 then v_b := v_b / 100; end if;

  return round(v_a * v_b, 6);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_obter_dados_cuba(p_cuba_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_norm text;
  v_codigo text;
  v_nome text;
  v_preco numeric := 0;
begin
  if p_cuba_input is null or trim(p_cuba_input) = '' then
    return jsonb_build_object('codigo', null, 'nome', null, 'preco', 0.00);
  end if;

  v_norm := public.norm_txt(p_cuba_input);

  if v_norm in ('cliente', 'cortesia', 'cuba do cliente', 'cuba cliente', 'propria', 'sem cuba')
     or v_norm like '%cliente%' or v_norm like '%cortesia%' then
    return jsonb_build_object('codigo', 'cliente', 'nome', 'Cuba do Cliente (Cortesia colagem R$ 0,00)', 'preco', 0.00);
  end if;

  select r.codigo, r.nome, round(r.preco_centavos::numeric / 100.0, 2)
    into v_codigo, v_nome, v_preco
    from public.lojao_regras_extras r
   where r.ativo
     and (r.codigo = p_cuba_input or public.norm_txt(r.nome) = v_norm or r.codigo = 'cuba_' || v_norm)
   limit 1;

  if found and v_preco is not null then
    return jsonb_build_object('codigo', v_codigo, 'nome', v_nome, 'preco', v_preco);
  end if;

  if v_norm like '%oval%' and (v_norm like '%pequen%' or v_norm like '%65%') and v_norm not like '%inox%' then
    return jsonb_build_object('codigo', 'cuba_oval_pequena_branca', 'nome', 'Cuba Oval Pequena Branca Louça', 'preco', 65.00);
  elsif v_norm like '%oval%' and (v_norm like '%grand%' or v_norm like '%75%') and v_norm not like '%inox%' then
    return jsonb_build_object('codigo', 'cuba_oval_grande_branca', 'nome', 'Cuba Oval Grande Branca Louça', 'preco', 75.00);
  elsif v_norm like '%redonda%' and (v_norm like '%24%' or v_norm like '%inox%') then
    return jsonb_build_object('codigo', 'cuba_redonda_inox_24', 'nome', 'Cuba Redonda Inox 24cm', 'preco', 89.00);
  elsif v_norm like '%oval%' and v_norm like '%inox%' then
    return jsonb_build_object('codigo', 'cuba_oval_inox_26x36', 'nome', 'Cuba Oval Inox 26x36', 'preco', 110.00);
  elsif v_norm like '%40x34x16%' or v_norm like '%40%34%16%' then
    return jsonb_build_object('codigo', 'cuba_40x34x16', 'nome', 'Cuba Inox 40x34x16', 'preco', 169.00);
  elsif v_norm like '%47x30x15%' or v_norm like '%47%30%15%' then
    return jsonb_build_object('codigo', 'cuba_47x30x15', 'nome', 'Cuba Inox 47x30x15', 'preco', 189.00);
  elsif v_norm like '%40x34x17%' or (v_norm like '%profunda%' and v_norm like '%40%') then
    return jsonb_build_object('codigo', 'cuba_40x34x17', 'nome', 'Cuba Inox Profunda 40x34x17', 'preco', 219.00);
  elsif v_norm like '%47x30x17%' or (v_norm like '%profunda%' and v_norm like '%47%') then
    return jsonb_build_object('codigo', 'cuba_47x30x17', 'nome', 'Cuba Inox Profunda 47x30x17', 'preco', 229.00);
  elsif v_norm like '%56x34x15%' or (v_norm like '%grande%' and v_norm like '%56%15%') then
    return jsonb_build_object('codigo', 'cuba_56x34x15', 'nome', 'Cuba Inox Grande 56x34x15', 'preco', 229.00);
  elsif v_norm like '%56x34x17%' or (v_norm like '%56%' and v_norm like '%17%') then
    return jsonb_build_object('codigo', 'cuba_56x34x17', 'nome', 'Cuba Inox Grande Profunda 56x34x17', 'preco', 269.00);
  end if;

  return jsonb_build_object('codigo', 'cuba_avulsa', 'nome', p_cuba_input, 'preco', 0.00);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_obter_parametro(p_chave text, p_default numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_val numeric;
begin
  select valor into v_val from public.lojao_parametros_v3 where chave = p_chave;
  return coalesce(v_val, p_default);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_pendencias_de_rascunho()
 RETURNS TABLE(id uuid, lead_id text, conversa_id text, cliente_nome text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select distinct on (s.conversa_id) s.id, s.lead_id::text, s.conversa_id::text, s.cliente_nome
  from public.lojao_orcamento_solicitacoes s
  where s.status = 'rascunho' and s.rascunho_criado_em is null and s.conversa_id is not null
  order by s.conversa_id, s.criado_em desc
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_recalcular_orcamento(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.lojao_orcamento_solicitacoes%rowtype;
  v_resultado jsonb;
  v_total bigint;
begin
  select * into v_row
    from public.lojao_orcamento_solicitacoes
   where token_aprovacao = p_token
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'erro', 'nao_encontrado');
  end if;

  if v_row.status <> 'rascunho' then
    return jsonb_build_object('ok', false, 'erro', 'ja_processado', 'status', v_row.status);
  end if;

  v_resultado := public.fn_lojao_calcular_orcamento(v_row.payload, v_row.modo);
  v_total := coalesce((v_resultado->>'total_centavos')::bigint, 0);

  update public.lojao_orcamento_solicitacoes
     set resultado = v_resultado,
         total_centavos = v_total,
         total_final_centavos = v_total,
         atualizado_em = now()
   where id = v_row.id;

  return jsonb_build_object('ok', true, 'resultado', v_resultado);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_registrar_orcamento(p_payload jsonb, p_modo text DEFAULT 'producao'::text, p_idempotency_key text DEFAULT NULL::text, p_cliente jsonb DEFAULT NULL::jsonb, p_canal text DEFAULT NULL::text, p_conversa_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_resultado jsonb;
  v_id uuid;
  v_token uuid;
  v_existente record;
  v_nome text;
  v_telefone text;
  v_total bigint;
  v_last8 text;
  v_cliente_id uuid;
  v_nome_existente text;
  v_user_id uuid;
  v_numero_orcamento text;
  v_orcamento_id uuid;
  v_valor_total numeric;
  v_item jsonb;
  v_extra jsonb;
  v_item_produto_id uuid;
  v_item_variacao text;
  v_item_produto_nome text;
  v_item_qtd numeric;
  v_item_preco_unit numeric;
  v_item_subtotal numeric;
  v_item_medidas text;
  v_item_descricao text;
  v_observacoes text;
  v_versao_regra text := 'v3.0';
begin
  -- 1. Verificação de idempotência
  if p_idempotency_key is not null and btrim(p_idempotency_key) <> '' then
    select id, token_aprovacao, resultado, status, orcamento_id
      into v_existente
      from public.lojao_orcamento_solicitacoes
     where idempotency_key = p_idempotency_key
     limit 1;

    if found then
      return jsonb_build_object(
        'ok', true,
        'idempotente', true,
        'solicitacao_id', v_existente.id,
        'token_aprovacao', v_existente.token_aprovacao,
        'orcamento_id', v_existente.orcamento_id,
        'status', v_existente.status,
        'resultado', v_existente.resultado
      );
    end if;
  end if;

  -- 2. Cálculo determinístico com o motor v3.0 (com fallback se falhar)
  begin
    v_resultado := public.calcular_orcamento_v3(p_payload);
    if v_resultado is null or not (v_resultado ? 'ok') or (v_resultado->>'ok')::boolean is false then
      v_resultado := public.fn_lojao_calcular_orcamento(p_payload, p_modo);
      v_versao_regra := 'legacy';
    end if;
  exception when others then
    v_resultado := public.fn_lojao_calcular_orcamento(p_payload, p_modo);
    v_versao_regra := 'legacy';
  end;

  if not (v_resultado ? 'ok') then
    return v_resultado;
  end if;

  -- 3. Identificação e Criação do Cliente na tabela clientes
  v_nome := nullif(btrim(coalesce(p_cliente->>'nome', '')), '');
  v_telefone := nullif(btrim(coalesce(p_cliente->>'telefone', '')), '');
  v_total := coalesce((v_resultado->>'total_centavos')::bigint, 0);

  if v_telefone is not null then
    v_last8 := right(regexp_replace(v_telefone, '\D', '', 'g'), 8);
    if v_nome is null then
      v_nome := 'Cliente WhatsApp ' || coalesce(v_last8, '');
    end if;

    select id, nome into v_cliente_id, v_nome_existente
      from public.clientes
     where (telefone_last8 is not null and telefone_last8 = v_last8)
        or right(regexp_replace(telefone, '\D', '', 'g'), 8) = v_last8
     order by updated_at desc nulls last
     limit 1;

    if found then
      if (v_nome_existente is null or v_nome_existente ~* '^(cliente|lead|whatsapp)') and v_nome !~* '^(cliente|lead|whatsapp)' then
        update public.clientes set nome = v_nome, updated_at = now() where id = v_cliente_id;
      end if;
    else
      insert into public.clientes (nome, telefone, created_at, updated_at)
      values (v_nome, v_telefone, now(), now())
      returning id into v_cliente_id;
    end if;
  elsif v_nome is not null then
    select id into v_cliente_id
      from public.clientes
     where lower(btrim(nome)) = lower(v_nome)
     limit 1;

    if not found then
      insert into public.clientes (nome, telefone, created_at, updated_at)
      values (v_nome, 'Não informado', now(), now())
      returning id into v_cliente_id;
    end if;
  else
    select id into v_cliente_id from public.clientes where nome = 'Consumidor Final' limit 1;
    if v_cliente_id is null then
      insert into public.clientes (nome, telefone, created_at, updated_at)
      values ('Consumidor Final', 'Não informado', now(), now())
      returning id into v_cliente_id;
    end if;
  end if;

  -- 4. Identificação do usuário dono para atribuição
  select id into v_user_id 
    from auth.users 
   where email = 'lojaodomarmore@gmail.com' 
   limit 1;
  if v_user_id is null then
    select id into v_user_id from auth.users order by created_at asc limit 1;
  end if;

  -- 5. Criação do orçamento na tabela public.orcamentos
  v_numero_orcamento := 'ORC-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));
  v_valor_total := coalesce((v_resultado->>'total')::numeric, round(v_total::numeric / 100.0, 2));
  v_observacoes := 'Orçamento gerado via WhatsApp';

  insert into public.orcamentos (
    numero_orcamento,
    cliente_id,
    user_id,
    forma_pagamento,
    observacoes,
    valor_total,
    status,
    data_validade,
    desconto,
    desconto_tipo,
    regra_versao,
    created_at,
    updated_at
  ) values (
    v_numero_orcamento,
    v_cliente_id,
    v_user_id,
    'a_vista_pix',
    v_observacoes,
    v_valor_total,
    'pendente',
    (current_date + interval '15 days')::date,
    coalesce((v_resultado->>'desconto')::numeric, 0),
    'porcentagem',
    v_versao_regra,
    now(),
    now()
  )
  returning id into v_orcamento_id;

  -- 6. Inserção de cada item em public.itens_orcamento
  for v_item in select value from jsonb_array_elements(coalesce(v_resultado->'itens', '[]'::jsonb))
  loop
    v_item_produto_id := nullif(v_item->>'produto_id', '')::uuid;
    if v_item_produto_id is null then
      select id into v_item_produto_id from public.produtos order by created_at asc limit 1;
    end if;

    v_item_variacao := coalesce(v_item->>'tipo_peca', v_item->>'variacao', 'Peça sob medida');
    v_item_produto_nome := coalesce(v_item->>'pedra', v_item->>'produto', 'Mármore/Granito');
    v_item_qtd := coalesce((v_item->>'quantidade')::numeric, 1);
    v_item_preco_unit := coalesce((v_item->>'valor_unitario')::numeric, (v_item->>'preco_unitario')::numeric, 0);
    v_item_subtotal := coalesce((v_item->>'subtotal')::numeric, 0);

    -- Medidas formatadas
    if (v_item->>'comprimento_cm') is not null and (v_item->>'largura_cm') is not null and (v_item->>'largura_cm')::numeric > 0 then
      v_item_medidas := round(((v_item->>'comprimento_cm')::numeric / 100.0), 2)::text || ' x ' || round(((v_item->>'largura_cm')::numeric / 100.0), 2)::text || ' m';
    elsif (v_item->>'comprimento_cm') is not null then
      v_item_medidas := round(((v_item->>'comprimento_cm')::numeric / 100.0), 2)::text || ' m';
    else
      v_item_medidas := null;
    end if;

    -- Descrição com acabamentos/extras se houver
    v_item_descricao := v_item_produto_nome || ' - ' || v_item_variacao;

    if v_item ? 'extras' and jsonb_array_length(v_item->'extras') > 0 then
      for v_extra in select value from jsonb_array_elements(v_item->'extras')
      loop
        v_item_descricao := v_item_descricao || ' | ' || coalesce(v_extra->>'nome', v_extra->>'codigo', '');
      end loop;
    end if;

    insert into public.itens_orcamento (
      orcamento_id,
      produto_id,
      descricao,
      quantidade,
      preco_unitario,
      preco_total,
      medidas,
      variacao,
      memoria_calculo,
      detalhes_calculo,
      created_at
    ) values (
      v_orcamento_id,
      v_item_produto_id,
      v_item_descricao,
      v_item_qtd,
      v_item_preco_unit,
      v_item_subtotal,
      v_item_medidas,
      v_item_variacao,
      v_item->'memoria_calculo',
      v_item,
      now()
    );
  end loop;

  -- 7. Registro na fila de solicitações do motor
  insert into public.lojao_orcamento_solicitacoes (
    idempotency_key, cliente_nome, cliente_telefone, canal, conversa_id,
    payload, resultado, modo, status, total_centavos, total_final_centavos,
    orcamento_id
  ) values (
    nullif(btrim(coalesce(p_idempotency_key, '')), ''),
    v_nome, v_telefone, p_canal, p_conversa_id,
    p_payload, v_resultado, p_modo, 'rascunho', v_total, v_total,
    v_orcamento_id
  )
  returning id, token_aprovacao into v_id, v_token;

  return jsonb_build_object(
    'ok', true,
    'idempotente', false,
    'solicitacao_id', v_id,
    'token_aprovacao', v_token,
    'orcamento_id', v_orcamento_id,
    'numero_orcamento', v_numero_orcamento,
    'cliente_id', v_cliente_id,
    'status', 'rascunho',
    'versao_motor', v_versao_regra,
    'resultado', v_resultado
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_sincronizar_contato(p_nome text, p_telefone text, p_email text DEFAULT NULL::text, p_origem text DEFAULT 'crm'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_nome text;
  v_telefone text;
  v_last8 text;
  v_cliente_id uuid;
  v_nome_existente text;
begin
  v_nome := nullif(btrim(coalesce(p_nome, '')), '');
  v_telefone := nullif(btrim(coalesce(p_telefone, '')), '');

  if v_telefone is null and v_nome is null then
    return jsonb_build_object('ok', false, 'erro', 'nome_ou_telefone_obrigatorio');
  end if;

  if v_telefone is not null then
    v_last8 := right(regexp_replace(v_telefone, '\D', '', 'g'), 8);
    if v_nome is null then
      v_nome := 'Contato ' || coalesce(v_last8, '');
    end if;

    select id, nome into v_cliente_id, v_nome_existente
      from public.clientes
     where (telefone_last8 is not null and telefone_last8 = v_last8)
        or right(regexp_replace(telefone, '\D', '', 'g'), 8) = v_last8
     order by updated_at desc nulls last
     limit 1;

    if found then
      if (v_nome_existente is null or v_nome_existente ~* '^(cliente|lead|whatsapp|contato)') 
         and v_nome !~* '^(cliente|lead|whatsapp|contato)' then
        update public.clientes 
           set nome = v_nome, 
               email = coalesce(nullif(btrim(p_email), ''), email),
               updated_at = now() 
         where id = v_cliente_id;
      end if;
      return jsonb_build_object('ok', true, 'acao', 'atualizado', 'cliente_id', v_cliente_id);
    else
      insert into public.clientes (nome, telefone, email, created_at, updated_at)
      values (v_nome, v_telefone, nullif(btrim(p_email), ''), now(), now())
      returning id into v_cliente_id;
      return jsonb_build_object('ok', true, 'acao', 'criado', 'cliente_id', v_cliente_id);
    end if;
  else
    select id into v_cliente_id
      from public.clientes
     where lower(btrim(nome)) = lower(v_nome)
     limit 1;

    if found then
      return jsonb_build_object('ok', true, 'acao', 'existente', 'cliente_id', v_cliente_id);
    else
      insert into public.clientes (nome, telefone, email, created_at, updated_at)
      values (v_nome, 'Não informado', nullif(btrim(p_email), ''), now(), now())
      returning id into v_cliente_id;
      return jsonb_build_object('ok', true, 'acao', 'criado', 'cliente_id', v_cliente_id);
    end if;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_texto_orcamento(p_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.lojao_orcamento_solicitacoes%rowtype;
  v_item jsonb;
  v_extra jsonb;
  v_linhas text := '';
  v_total bigint;
  v_status text;
  v_pendencias text;
  v_validade text;
begin
  select * into v_row from public.lojao_orcamento_solicitacoes where id = p_id;
  if not found then
    return null;
  end if;

  v_status := coalesce(v_row.resultado->>'status', 'desconhecido');
  v_total := coalesce(v_row.total_final_centavos, v_row.total_centavos, 0);
  v_validade := coalesce(v_row.resultado->>'validade', v_row.expira_em::text);

  for v_item in select value from jsonb_array_elements(coalesce(v_row.resultado->'itens', '[]'::jsonb))
  loop
    if coalesce(v_item->>'status', 'ok') <> 'ok' then
      v_linhas := v_linhas || format(
        E'- %s (%s): %s%s',
        coalesce(v_item->>'produto', '?'),
        coalesce(v_item->>'variacao', '?'),
        coalesce(v_item->>'motivo', 'sem cálculo'),
        E'\n'
      );
    else
      v_linhas := v_linhas || format(
        E'- %s — %s: %s x %s cm%s | área %s m² | R$ %s%s',
        coalesce(v_item->>'produto', '?'),
        coalesce(v_item->>'variacao', '?'),
        coalesce(v_item->>'comprimento_cm', '?'),
        coalesce(v_item->>'largura_cm', '?'),
        case when coalesce((v_item->>'quantidade')::numeric, 1) > 1
             then format(' (x%s)', v_item->>'quantidade') else '' end,
        coalesce(v_item->>'area_cobrada_m2', v_item->>'area_m2'),
        public.fn_lojao_brl((v_item->>'subtotal_centavos')::bigint),
        case when v_item->>'preco_status' = 'rascunho'
             then ' [preço ainda não validado pelo responsável]' else '' end
      );
      for v_extra in select value from jsonb_array_elements(coalesce(v_item->'extras', '[]'::jsonb))
      loop
        v_linhas := v_linhas || format(
          E'    + %s: R$ %s',
          coalesce(v_extra->>'nome', v_extra->>'codigo'),
          public.fn_lojao_brl((v_extra->>'valor_centavos')::bigint)
        );
      end loop;
      v_linhas := v_linhas || E'\n';
    end if;
  end loop;

  if v_linhas = '' then
    v_linhas := E'(nenhum item calculado)' || E'\n';
  end if;

  v_pendencias := '';
  if jsonb_array_length(coalesce(v_row.resultado->'pendencias', '[]'::jsonb)) > 0 then
    v_pendencias := E'\nPendências: ' || coalesce(v_row.resultado->>'status', '') ||
      ' — ' || (select string_agg(coalesce(p->>'motivo', '?'), ', ')
                from jsonb_array_elements(v_row.resultado->'pendencias') p) || E'\n';
  end if;

  return format(
    E'ORÇAMENTO — Lojão dos Mármores\nCliente: %s\n%s\nItens:\n%s%sTotal: R$ %s%s',
    coalesce(nullif(v_row.cliente_nome, ''), '(não informado)'),
    case when v_validade is not null then 'Validade: ' || v_validade || E'\n' else '' end,
    v_linhas,
    v_pendencias,
    public.fn_lojao_brl(v_total),
    case when v_status = 'sob_consulta'
         then E'\n\nATENÇÃO: este orçamento ainda não pode ser enviado — falta validar preço ou medidas.'
         else '' end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_lojao_webhook_valido(p_corpo text, p_assinatura text, p_entrega text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'extensions', 'pg_temp'
AS $function$
declare
  v_segredo text;
  v_ts bigint;
  v_v1 text;
  v_esperado text;
begin
  select decrypted_secret into v_segredo
    from vault.decrypted_secrets
   where name = 'crm_webhook_lojao';

  if v_segredo is null or p_corpo is null or p_assinatura is null then
    return false;
  end if;

  v_ts := nullif(substring(p_assinatura from 't=([0-9]+)'), '')::bigint;
  v_v1 := nullif(substring(p_assinatura from 'v1=([0-9a-fA-F]+)'), '');

  if v_ts is null or v_v1 is null then
    return false;
  end if;

  if abs(extract(epoch from now())::bigint - v_ts) > 300 then
    return false;
  end if;

  v_esperado := encode(
    hmac(v_ts::text || '.' || coalesce(p_entrega, '') || '.' || p_corpo, v_segredo, 'sha256'),
    'hex'
  );

  return v_esperado = lower(v_v1);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_orcamento_number()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- sem 0/O/1/I para evitar confusão visual
  new_code TEXT;
  code_body TEXT;
  i INTEGER;
BEGIN
  LOOP
    code_body := '';
    FOR i IN 1..8 LOOP
      code_body := code_body || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    END LOOP;
    new_code := 'ORC-' || code_body;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.orcamentos WHERE numero_orcamento = new_code);
  END LOOP;
  RETURN new_code;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_pedido_number()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  new_code TEXT;
  code_body TEXT;
  i INTEGER;
BEGIN
  LOOP
    code_body := '';
    FOR i IN 1..8 LOOP
      code_body := code_body || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    END LOOP;
    new_code := 'PED-' || code_body;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.pedidos WHERE numero_pedido = new_code);
  END LOOP;
  RETURN new_code;
END;
$function$
;

