CREATE OR REPLACE FUNCTION public.inserir_relatorio(p_nome_relatorio text, p_periodo_dias integer, p_user_id uuid, p_dados jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_relatorio_id UUID;
BEGIN
    INSERT INTO relatorios (
        nome_relatorio,
        periodo_dias,
        user_id,
        total_vendas,
        total_pedidos,
        total_clientes,
        total_produtos,
        total_orcamentos,
        total_fornecedores,
        ticket_medio_pedidos,
        ticket_medio_orcamentos,
        total_pago_fornecedores,
        pedidos_aguardando_producao,
        pedidos_em_producao,
        pedidos_aguardando_retirada,
        pedidos_finalizado,
        pedidos_entregue,
        orcamentos_pendentes,
        orcamentos_aprovados,
        orcamentos_rejeitados,
        top_clientes,
        produtos_mais_vendidos,
        vendas_por_mes,
        evolucao_ticket_medio,
        crescimento_clientes,
        analise_fornecedores,
        pagamentos_recentes
    ) VALUES (
        p_nome_relatorio,
        p_periodo_dias,
        p_user_id,
        (p_dados->>'total_vendas')::DECIMAL,
        (p_dados->>'total_pedidos')::INTEGER,
        (p_dados->>'total_clientes')::INTEGER,
        (p_dados->>'total_produtos')::INTEGER,
        (p_dados->>'total_orcamentos')::INTEGER,
        (p_dados->>'total_fornecedores')::INTEGER,
        (p_dados->>'ticket_medio_pedidos')::DECIMAL,
        (p_dados->>'ticket_medio_orcamentos')::DECIMAL,
        (p_dados->>'total_pago_fornecedores')::DECIMAL,
        (p_dados->>'pedidos_aguardando_producao')::INTEGER,
        (p_dados->>'pedidos_em_producao')::INTEGER,
        (p_dados->>'pedidos_aguardando_retirada')::INTEGER,
        (p_dados->>'pedidos_finalizado')::INTEGER,
        (p_dados->>'pedidos_entregue')::INTEGER,
        (p_dados->>'orcamentos_pendentes')::INTEGER,
        (p_dados->>'orcamentos_aprovados')::INTEGER,
        (p_dados->>'orcamentos_rejeitados')::INTEGER,
        p_dados->'top_clientes',
        p_dados->'produtos_mais_vendidos',
        p_dados->'vendas_por_mes',
        p_dados->'evolucao_ticket_medio',
        p_dados->'crescimento_clientes',
        p_dados->'analise_fornecedores',
        p_dados->'pagamentos_recentes'
    ) RETURNING id INTO v_relatorio_id;
    
    -- Inserir no histórico
    INSERT INTO historico_relatorios (relatorio_id, acao, user_id, detalhes)
    VALUES (v_relatorio_id, 'criado', p_user_id, p_dados);
    
    RETURN v_relatorio_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.norm_txt(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select lower(trim(translate(coalesce(t, ''),
    'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇçÑñ',
    'AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCcNn')));
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_orcamento(p_cliente_id uuid, p_user_id uuid, p_itens jsonb, p_observacoes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_orcamento_id    uuid;
  v_numero          text;
  v_item            jsonb;
  v_nome            text;
  v_variacao        text;
  v_produto         public.produtos%rowtype;
  v_preco           numeric;
  v_qtd             numeric;
  v_registrados     int := 0;
  v_total           numeric := 0;
  v_nao_encontrados text[] := '{}';
begin
  if p_cliente_id is null then
    raise exception 'cliente_id e obrigatorio';
  end if;
  if not exists (select 1 from public.clientes where id = p_cliente_id) then
    raise exception 'cliente % nao existe', p_cliente_id;
  end if;
  if p_itens is null or jsonb_typeof(p_itens) <> 'array' or jsonb_array_length(p_itens) = 0 then
    raise exception 'itens deve ser um array com pelo menos um item';
  end if;

  v_numero := 'ORC-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  insert into public.orcamentos (cliente_id, user_id, numero_orcamento, observacoes, status, valor_total)
  values (p_cliente_id, p_user_id, v_numero, nullif(p_observacoes, ''), 'pendente', 0)
  returning id into v_orcamento_id;

  for v_item in select * from jsonb_array_elements(p_itens)
  loop
    v_nome := public.norm_txt(v_item->>'produto_nome');
    continue when v_nome = '';

    select * into v_produto
      from public.produtos
     where ativo and public.norm_txt(nome) = v_nome
     limit 1;

    if not found then
      select * into v_produto
        from public.produtos
       where ativo
         and (public.norm_txt(nome) like '%' || v_nome || '%'
              or v_nome like '%' || public.norm_txt(nome) || '%')
       order by length(nome)
       limit 1;
    end if;

    if not found then
      v_nao_encontrados := v_nao_encontrados || (v_item->>'produto_nome');
      continue;
    end if;

    v_variacao := nullif(v_item->>'variacao', '');

    -- preco da variacao escolhida; se nao houver, cai no preco do produto
    v_preco := null;
    if v_variacao is not null then
      select pv.preco into v_preco
        from public.produto_variacoes pv
       where pv.produto_id = v_produto.id
         and public.norm_txt(pv.variacao) = public.norm_txt(v_variacao)
       limit 1;
    end if;
    v_preco := coalesce(v_preco, v_produto.preco_unitario, 0);

    v_qtd := coalesce(nullif(v_item->>'quantidade', '')::numeric, 1);

    insert into public.itens_orcamento
      (orcamento_id, produto_id, descricao, variacao, quantidade, medidas, preco_unitario, preco_total)
    values (
      v_orcamento_id,
      v_produto.id,
      trim(v_produto.nome) || coalesce(' - ' || v_variacao, ''),
      v_variacao,
      v_qtd,
      nullif(v_item->>'medidas', ''),
      v_preco,
      v_qtd * v_preco
    );

    v_registrados := v_registrados + 1;
    v_total := v_total + (v_qtd * v_preco);
  end loop;

  if v_registrados = 0 then
    raise exception 'Nenhum produto encontrado no catalogo: %', array_to_string(v_nao_encontrados, ', ');
  end if;

  update public.orcamentos set valor_total = v_total where id = v_orcamento_id;

  return jsonb_build_object(
    'numero_orcamento',  v_numero,
    'itens_registrados', v_registrados,
    'valor_total',       v_total,
    'nao_encontrados',   to_jsonb(v_nao_encontrados)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.repetir_ultimo_orcamento(p_cliente_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_ultimo  public.orcamentos%rowtype;
  v_novo_id uuid;
  v_numero  text;
  v_n       int;
  v_total   numeric;
begin
  select * into v_ultimo
    from public.orcamentos
   where cliente_id = p_cliente_id
   order by created_at desc
   limit 1;

  if not found then
    raise exception 'Nenhum orcamento anterior encontrado para este cliente';
  end if;
  if not exists (select 1 from public.itens_orcamento where orcamento_id = v_ultimo.id) then
    raise exception 'O orcamento anterior nao possui itens para repetir';
  end if;

  v_numero := 'ORC-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  insert into public.orcamentos
    (cliente_id, user_id, numero_orcamento, observacoes, forma_pagamento, status, valor_total)
  values
    (p_cliente_id, p_user_id, v_numero, v_ultimo.observacoes, v_ultimo.forma_pagamento, 'pendente', 0)
  returning id into v_novo_id;

  insert into public.itens_orcamento
    (orcamento_id, produto_id, descricao, variacao, quantidade, medidas, preco_unitario, preco_total)
  select v_novo_id, produto_id, descricao, variacao, quantidade, medidas,
         coalesce(preco_unitario, 0), coalesce(quantidade, 1) * coalesce(preco_unitario, 0)
    from public.itens_orcamento
   where orcamento_id = v_ultimo.id;
  get diagnostics v_n = row_count;

  select coalesce(sum(preco_total), 0) into v_total
    from public.itens_orcamento where orcamento_id = v_novo_id;
  update public.orcamentos set valor_total = v_total where id = v_novo_id;

  return jsonb_build_object(
    'numero_orcamento',  v_numero,
    'itens_registrados', v_n,
    'valor_total',       v_total
  );
end;
$function$
;

