CREATE OR REPLACE FUNCTION public.tg_orcamento_request()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_itens jsonb;
  v_res   jsonb;
begin
  if new.repetir_ultimo then
    v_res := public.repetir_ultimo_orcamento(new.cliente_id, new.user_id);
  else
    -- itens chega como texto para nao depender de como o n8n serializa jsonb
    begin
      v_itens := new.itens::jsonb;
    exception when others then
      raise exception 'itens nao e um JSON valido: %', left(coalesce(new.itens, ''), 200);
    end;
    v_res := public.registrar_orcamento(new.cliente_id, new.user_id, v_itens, new.observacoes);
  end if;

  new.numero_orcamento  := v_res->>'numero_orcamento';
  new.itens_registrados := (v_res->>'itens_registrados')::int;
  new.nao_encontrados   := coalesce(v_res->'nao_encontrados', '[]'::jsonb);
  return new;
end;
$function$
;

